// FindMethod looks up a method by service and method name (case-insensitive).
func FindMethod(service, method string) *MethodEntry {
	for i := range Registry {
		if !strings.EqualFold(Registry[i].Name, service) {
			continue
		}

		for j := range Registry[i].Methods {
			if strings.EqualFold(Registry[i].Methods[j].Method, method) {
				return &Registry[i].Methods[j]
			}
		}
	}

	return nil
}

// SearchMethods returns methods whose name or description contains the query (case-insensitive).
func SearchMethods(query string) []MethodEntry {
	q := strings.ToLower(query)

	var results []MethodEntry

	for _, svc := range Registry {
		for _, m := range svc.Methods {
			if strings.Contains(strings.ToLower(m.Method), q) ||
				strings.Contains(strings.ToLower(m.Description), q) ||
				strings.Contains(strings.ToLower(m.Service), q) {
				results = append(results, m)
			}
		}
	}

	return results
}
